void new(InventTransferTable _transferTable)
{
    this.init(_transferTable);
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_transferLine">Invent Transfer Line</param>
/// <returns>Transfer order quantity</returns>
protected InventTransferQty lineShipQty(InventTransferLine _transferLine)
{
    return _transferLine.QtyTransfer;
}
